const HUK=Object.keys(HUX).sort((a,b)=>b.length-a.length),HURE=new RegExp("(?<![\\p{L}])("+HUK.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|")+")(?![\\p{L}])","gu");
